sql.where:
BBS_ID = #{bbsId}



			AND PST_TTL LIKE CONCAT('%', #{searchKeyword}, '%')


			AND (PST_CN LIKE CONCAT('%', #{searchKeyword}, '%'))


			AND (PST_TTL LIKE CONCAT('%', #{searchKeyword}, '%') OR PST_CN LIKE CONCAT('%', #{searchKeyword}, '%'))




	AND CTGR_CD = #{ctgrCd}


	AND DATE(REG_DT) >= #{startDate}


	AND DATE(REG_DT) <= #{endDate}
